script:
frappe.ui.form.on('Leave Request', {
    from_date: function(frm) {
        calculate_days(frm);
    },

    to_date: function(frm) {
        calculate_days(frm);
    }
});

function calculate_days(frm) {
    if (frm.doc.from_date && frm.doc.to_date) {

        let from_date = frappe.datetime.str_to_obj(frm.doc.from_date);
        let to_date = frappe.datetime.str_to_obj(frm.doc.to_date);

        let difference = to_date - from_date;

        let days = difference / (1000 * 60 * 60 * 24);

        frm.set_value('total_days', days + 1);
    }
}

frappe.ui.form.on("Project_name", {
    refresh(frm) {
        if (
            frappe.user_roles.includes("Administrator")
        ) {
            frm.enable_save();
        } else {
            frm.disable_save();
        }
    }
});

frappe.listview_settings["details"] = {

    dropdown_button: {
        get_label() {
            return "Actions";
        },

        buttons: [
            {
                show(doc) {
                    return doc.status === "Active";
                },

                get_label(doc) {
                    return "View";
                },

                get_description(doc) {
                    return `View ${doc.name1}`;
                },

                action(doc) {
                    frappe.set_route("Form", "details", doc.name);
                }
            },

            {
                show(doc) {
                    return doc.status === "Active";
                },

                get_label(doc) {
                    return "Message";
                },

                get_description(doc) {
                    return `Send message to ${doc.name1}`;
                },

                action(doc) {
                    frappe.msgprint(`Hello ${doc.name1}`);
                }
            }
        ]
    }
};

frappe.ui.form.on('User', {
    refresh(frm) {
        frm.add_custom_button('Send Welcome Email', () => {
            frappe.msgprint('Email Sent!');
        }, 'Actions');
    }
});
